import json, math
from fractions import Fraction

# cot(x/2) = (1+cos x)/sin x and 1-cos^4 x = sin^2 x (1+cos^2 x),
# so the integrand is (1+cos x)(1+cos^2 x) sin x. With u = cos x the integral
# becomes the integral over u in [0,1] of (1+u)(1+u^2) = 1+u+u^2+u^3.
coeffs = [1, 1, 1, 1]
exact = sum(Fraction(c, k + 1) for k, c in enumerate(coeffs))

# Independent numeric check with composite Simpson on the original integrand
def f(x):
    if x == 0:
        return 0.0  # limit: cot(x/2)*(1-cos^4 x) ~ (2/x)*(2x^2) -> 0
    return (math.cos(x / 2) / math.sin(x / 2)) * (1 - math.cos(x) ** 4)

n = 2000
a, b = 0.0, math.pi / 2
h = (b - a) / n
s = f(a) + f(b)
for i in range(1, n):
    s += (4 if i % 2 else 2) * f(a + i * h)
numeric = s * h / 3

ok = abs(numeric - float(exact)) < 1e-8
if ok:
    print(json.dumps({
        "final_answer": f"{exact.numerator}/{exact.denominator}",
        "evidence": {"exact": str(exact), "decimal": float(exact),
                     "simpson_check": numeric, "match": ok}
    }))
else:
    print("UNSUPPORTED")
